import sys, re, math, xml.etree.ElementTree as ET
def mm(a,b): return [[sum(a[i][k]*b[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
I=[[1 if i==j else 0 for j in range(4)] for i in range(4)]
def strip(t): return t.split('}')[-1]
def load(fn):
    root=ET.parse(fn).getroot()
    ns={'c':root.tag.split('}')[0][1:]} if '}' in root.tag else {}
    up=root.find('.//c:asset/c:up_axis',ns); up=up.text if up is not None else 'Y_UP'
    geoms={}
    for g in root.iter():
        if strip(g.tag)=='geometry':
            srcs={s.get('id'):[float(x) for x in s.find('c:float_array',ns).text.split()] for s in g.iter() if strip(s.tag)=='source' and s.find('c:float_array',ns) is not None}
            pos=None
            for v in g.iter():
                if strip(v.tag)=='vertices':
                    for inp in v:
                        if inp.get('semantic')=='POSITION': pos=srcs[inp.get('source')[1:]]
            geoms[g.get('id')]=[pos[i:i+3] for i in range(0,len(pos),3)] if pos else []
    res={'tags':{},'miny':1e9,'maxy':-1e9,'minx':1e9,'maxx':-1e9,'minz':1e9,'maxz':-1e9,'up':up}
    def walk(n,M):
        L=I
        for c in n:
            t=strip(c.tag)
            if t=='matrix':
                v=[float(x) for x in c.text.split()]; L=mm(L,[v[i*4:i*4+4] for i in range(4)])
            elif t=='translate':
                x,y,z=[float(a) for a in c.text.split()]; L=mm(L,[[1,0,0,x],[0,1,0,y],[0,0,1,z],[0,0,0,1]])
            elif t=='scale':
                x,y,z=[float(a) for a in c.text.split()]; L=mm(L,[[x,0,0,0],[0,y,0,0],[0,0,z,0],[0,0,0,1]])
            elif t=='rotate':
                x,y,z,a=[float(q) for q in c.text.split()]; a=math.radians(a); C,S=math.cos(a),math.sin(a); t1=1-C
                L=mm(L,[[t1*x*x+C,t1*x*y-S*z,t1*x*z+S*y,0],[t1*x*y+S*z,t1*y*y+C,t1*y*z-S*x,0],[t1*x*z-S*y,t1*y*z+S*x,t1*z*z+C,0],[0,0,0,1]])
        W=mm(M,L)
        name=n.get('name') or n.get('id') or ''
        if name.startswith('tag_'): res['tags'][name]=(W[0][3],W[1][3],W[2][3])
        for c in n:
            t=strip(c.tag)
            if t=='instance_geometry':
                for p in geoms.get(c.get('url')[1:],[]):
                    w=[sum(W[i][k]*p[k] for k in range(3))+W[i][3] for i in range(3)]
                    for ax,k in zip('xyz',w):
                        res['min'+ax]=min(res['min'+ax],k); res['max'+ax]=max(res['max'+ax],k)
            elif t=='node': walk(c,W)
    for vs in root.iter():
        if strip(vs.tag)=='visual_scene':
            for n in vs:
                if strip(n.tag)=='node': walk(n,I)
    return res
def loadobj(fn):
    ys=[];
    for l in open(fn):
        if l.startswith('v '): ys.append([float(a) for a in l.split()[1:4]])
    return {'up':'obj','tags':{},'miny':min(v[1] for v in ys),'maxy':max(v[1] for v in ys),'minx':min(v[0] for v in ys),'maxx':max(v[0] for v in ys),'minz':min(v[2] for v in ys),'maxz':max(v[2] for v in ys)}
for fn in sys.argv[1:]:
    r=loadobj(fn) if fn.endswith('.obj') else load(fn)
    print(fn, r['up'], 'x[%.2f,%.2f] y[%.2f,%.2f] z[%.2f,%.2f]'%(r['minx'],r['maxx'],r['miny'],r['maxy'],r['minz'],r['maxz']), {k:tuple(round(a,2) for a in v) for k,v in r['tags'].items() if 'landing' in k})
EOF
